CREATE TYPE "dish_status" AS ENUM ('DRAFT', 'VERIFIED');
CREATE TABLE "organization_units" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(120) NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "meal_types" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(50) NOT NULL, "sort_order" integer DEFAULT 0 NOT NULL);
CREATE TABLE "table_types" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(50) NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "daily_plans" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "plan_date" date NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX "daily_plan_date" ON "daily_plans" ("plan_date");
CREATE TABLE "dishes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(200) NOT NULL, "normalized_name" varchar(200) NOT NULL, "category" varchar(80) NOT NULL, "status" dish_status DEFAULT 'DRAFT' NOT NULL, "usage_count" integer DEFAULT 0 NOT NULL, "last_used_at" timestamptz, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "ingredients" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" varchar(160) NOT NULL, "unit" varchar(30) DEFAULT 'kg' NOT NULL, "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "headcount_entries" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "daily_plan_id" uuid NOT NULL REFERENCES "daily_plans"("id") ON DELETE CASCADE, "unit_id" uuid NOT NULL REFERENCES "organization_units"("id"), "meal_type_id" uuid NOT NULL REFERENCES "meal_types"("id"), "table_type_id" uuid NOT NULL REFERENCES "table_types"("id"), "count" integer DEFAULT 0 NOT NULL);
CREATE TABLE "menus" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "daily_plan_id" uuid NOT NULL REFERENCES "daily_plans"("id") ON DELETE CASCADE, "meal_type_id" uuid NOT NULL REFERENCES "meal_types"("id"), "table_type_id" uuid NOT NULL REFERENCES "table_types"("id"), "created_at" timestamptz DEFAULT now() NOT NULL, "updated_at" timestamptz DEFAULT now() NOT NULL);
CREATE TABLE "menu_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "menu_id" uuid NOT NULL REFERENCES "menus"("id") ON DELETE CASCADE, "dish_id" uuid NOT NULL REFERENCES "dishes"("id"), "category" varchar(80) NOT NULL, "note" varchar(500), "sort_order" integer DEFAULT 0 NOT NULL);
CREATE TABLE "dish_variants" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "dish_id" uuid NOT NULL REFERENCES "dishes"("id") ON DELETE CASCADE, "table_type_id" uuid NOT NULL REFERENCES "table_types"("id"));
CREATE TABLE "dish_ingredient_norms" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "dish_variant_id" uuid NOT NULL REFERENCES "dish_variants"("id") ON DELETE CASCADE, "ingredient_id" uuid NOT NULL REFERENCES "ingredients"("id"), "quantity_per_serving" numeric(12,4) NOT NULL);
CREATE TABLE "daily_ingredient_stocks" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "daily_plan_id" uuid NOT NULL REFERENCES "daily_plans"("id") ON DELETE CASCADE, "ingredient_id" uuid NOT NULL REFERENCES "ingredients"("id"), "available_quantity" numeric(12,3) DEFAULT 0 NOT NULL);
CREATE TABLE "shopping_items" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "daily_plan_id" uuid NOT NULL REFERENCES "daily_plans"("id") ON DELETE CASCADE, "ingredient_id" uuid NOT NULL REFERENCES "ingredients"("id"), "required_quantity" numeric(12,3) NOT NULL, "suggested_quantity" numeric(12,3) NOT NULL, "final_quantity" numeric(12,3) NOT NULL);
